let _markdown = "\n\n<Wrapper>\n    <TypeTable\n      type={{\n    \"name\": \"AutoTypeTableExample\",\n    \"description\": \"\",\n    \"entries\": [\n      {\n        \"name\": \"name\",\n        \"description\": \"Markdown syntax like links, `code` are supported.\\nSee https://fumadocs.dev/docs/ui/components/type-table\",\n        \"tags\": [],\n        \"type\": \"boolean | null\",\n        \"simplifiedType\": \"boolean | null\",\n        \"required\": true,\n        \"deprecated\": false\n      },\n      {\n        \"name\": \"fn\",\n        \"description\": \"\",\n        \"tags\": [\n          {\n            \"name\": \"param\",\n            \"text\": \"name - user name.\"\n          },\n          {\n            \"name\": \"param\",\n            \"text\": \"allowNull - is null value allowed.\"\n          },\n          {\n            \"name\": \"returns\",\n            \"text\": \"user ID\"\n          }\n        ],\n        \"type\": \"(name: string, allowNull?: boolean) => string\",\n        \"simplifiedType\": \"function\",\n        \"required\": true,\n        \"deprecated\": false\n      },\n      {\n        \"name\": \"options\",\n        \"description\": \"We love Shiki.\\n\\n```ts\\nconsole.log(\\\"Hello World, powered by Shiki\\\");\\n```\",\n        \"tags\": [\n          {\n            \"name\": \"default\",\n            \"text\": \"{ a: \\\"test\\\" }\"\n          }\n        ],\n        \"type\": \"Partial<{ a: unknown; }> | undefined\",\n        \"simplifiedType\": \"Partial<object>\",\n        \"required\": false,\n        \"deprecated\": false\n      }\n    ]\n  }}\n    />\n</Wrapper>\n\n<Callout title=\"Server Component only\" type=\"warn\">\n  You cannot use this in a client component, instead, try the [build-time MDX integration](/docs/integrations/typescript#mdx-integration) instead.\n</Callout>\n\n<FeedbackBlock id=\"effab056e6d101a8\" body=\"It generates a table for your docs based on TypeScript definitions.\">\n  It generates a table for your docs based on TypeScript definitions.\n</FeedbackBlock>\n\nUsage [#usage]\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm i fumadocs-typescript\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add fumadocs-typescript\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add fumadocs-typescript\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add fumadocs-typescript\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"c112bc05e252c42e\" body=\"Initialize the TypeScript compiler and add it as a MDX component.\">\n  Initialize the TypeScript compiler and add it as a MDX component.\n</FeedbackBlock>\n\n```tsx title=\"mdx-components.tsx\"\nimport defaultComponents from 'fumadocs-ui/mdx';\nimport type { MDXComponents } from 'mdx/types';\nimport { createGenerator, createFileSystemGeneratorCache } from 'fumadocs-typescript';\nimport { AutoTypeTable } from 'fumadocs-typescript/ui';\n\nconst generator = createGenerator({\n  // set a cache, necessary for serverless platform like Vercel\n  cache: createFileSystemGeneratorCache('.next/fumadocs-typescript'),\n});\n\nexport function getMDXComponents(components?: MDXComponents): MDXComponents {\n  return {\n    ...defaultComponents,\n    // [!code ++:3]\n    AutoTypeTable: (props) => <AutoTypeTable {...props} generator={generator} />,\n    ...components,\n  };\n}\n```\n\n<FeedbackBlock id=\"3939da31881187aa\" body=\"You can now reference <AutoTypeTable /> in your MDX content.\">\n  You can now reference `<AutoTypeTable />` in your MDX content.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"2fe8e8bac51b8dc6\" body=\"See TypeScript DocGen for more usages.\">\n  See [TypeScript DocGen](/docs/integrations/typescript) for more usages.\n</FeedbackBlock>\n\nFrom File [#from-file]\n\n<FeedbackBlock id=\"699876c051c29a83\" body=\"It accepts a path prop that points to a typescript file, and name for the exported type name.\">\n  It accepts a `path` prop that points to a typescript file, and `name` for the exported type name.\n</FeedbackBlock>\n\n```ts title=\"path/to/file.ts\"\nexport interface MyInterface {\n  name: string;\n}\n```\n\n```mdx title=\"content.mdx\"\n<AutoTypeTable path=\"./path/to/file.ts\" name=\"MyInterface\" />\n```\n\n<FeedbackBlock id=\"809bb53369d300ac\" body=\"The path is relative to your project directory (cwd), because AutoTypeTable is a React Server Component, it cannot access build-time information like MDX file path.\">\n  The path is relative to your project directory (`cwd`), because `AutoTypeTable` is a React Server Component, it cannot access build-time information like MDX file path.\n</FeedbackBlock>\n\nFrom Type [#from-type]\n\n<FeedbackBlock id=\"3ea3296597ea14ba\" body=\"You can specify the type to generate, without an actual TypeScript file.\">\n  You can specify the type to generate, without an actual TypeScript file.\n</FeedbackBlock>\n\n```mdx title=\"content.mdx\"\n<AutoTypeTable type=\"{ hello: string }\" />\n```\n\n<FeedbackBlock id=\"6529f87719094d7a\" body=\"When a path is given, it shares the same context as the TypeScript file.\">\n  When a `path` is given, it shares the same context as the TypeScript file.\n</FeedbackBlock>\n\n```ts title=\"file.ts\"\nexport type A = { hello: string };\n```\n\n```mdx title=\"content.mdx\"\n<AutoTypeTable path=\"file.ts\" type=\"A & { world: string }\" />\n```\n\n<FeedbackBlock id=\"aa77c29fde580632\" body=\"When type has multiple lines, the export statement and name prop are required.\">\n  When `type` has multiple lines, the export statement and `name` prop are required.\n</FeedbackBlock>\n\n```mdx title=\"content.mdx\"\n<AutoTypeTable\n  path=\"file.ts\"\n  name=\"B\"\n  type={`\nimport { ReactNode } from \"react\"\nexport type B = ReactNode | { world: string }\n`}\n/>\n```\n\nFunctions [#functions]\n\n<FeedbackBlock id=\"1de0e10e517c28f6\" body=\"Notice that only object type is allowed. For functions, you should wrap them into an object instead.\">\n  Notice that only object type is allowed. For functions, you should wrap them into an object instead.\n</FeedbackBlock>\n\n```ts\nexport interface MyInterface {\n  myFn: (input: string) => void;\n}\n```\n\nTypeScript Compiler [#typescript-compiler]\n\n<FeedbackBlock\n  id=\"28e90f3cffcb72d4\"\n  body=\"Under the hood, it uses the Typescript Compiler API to extract type information.\nYour tsconfig.json file in the current working directory will be loaded.\"\n>\n  Under the hood, it uses the [Typescript Compiler API](https://github.com/microsoft/TypeScript/wiki/Using-the-Compiler-API) to extract type information.\n  Your `tsconfig.json` file in the current working directory will be loaded.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"4e3fdf24e6ac299d\" body=\"You can change the compiler settings from createGenerator().\">\n  You can change the compiler settings from [`createGenerator()`](/docs/integrations/typescript).\n</FeedbackBlock>\n\n```ts\nimport { createGenerator, createFileSystemGeneratorCache } from 'fumadocs-typescript';\n\nconst generator = createGenerator({\n  tsconfigPath: './tsconfig.json',\n  // where to resolve relative paths (normally cwd)\n  basePath: './',\n  // other options...\n});\n```\n\nFile System [#file-system]\n\n<FeedbackBlock id=\"eab220e8e330869a\" body=\"It relies on the file system, hence, the page referencing this component must be built in build time. Rendering the component on serverless runtime may cause problems.\">\n  It relies on the file system, hence, the page referencing this component must be built in **build time**. Rendering the component on serverless runtime may cause problems.\n</FeedbackBlock>\n\nReferences [#references]\n\n<TypeTable\n  type={{\n  \"name\": \"AutoTypeTableProps\",\n  \"description\": \"\",\n  \"entries\": [\n    {\n      \"name\": \"path\",\n      \"description\": \"The path to source TypeScript file.\",\n      \"tags\": [],\n      \"type\": \"string | undefined\",\n      \"simplifiedType\": \"string\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"name\",\n      \"description\": \"Exported type name to generate from.\",\n      \"tags\": [],\n      \"type\": \"string | undefined\",\n      \"simplifiedType\": \"string\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"type\",\n      \"description\": \"Set the type to generate from.\\n\\nWhen used with `name`, it generates the type with `name` as export name.\\n\\n```ts\\nexport const myName = MyType;\\n```\\n\\nWhen `type` contains multiple lines, `export const` is not added.\\nYou need to export it manually, and specify the type name with `name`.\\n\\n```tsx\\n<AutoTypeTable\\n  path=\\\"./file.ts\\\"\\n  type={`import { ReactNode } from \\\"react\\\"\\n  export const MyName = ReactNode`}\\n  name=\\\"MyName\\\"\\n/>\\n```\",\n      \"tags\": [],\n      \"type\": \"string | undefined\",\n      \"simplifiedType\": \"string\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"generator\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"{ generateDocumentation(file: { path: string; content?: string; }, name: string | undefined, options?: GenerateOptions): Promise<GeneratedDoc[]>; generateTypeTable(props: BaseTypeTableProps, options?: GenerateTypeTableOptions): Promise<GeneratedDoc[]>; }\",\n      \"simplifiedType\": \"object\",\n      \"required\": true,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"renderMarkdown\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"((md: string) => Promise<ReactNode>) | undefined\",\n      \"simplifiedType\": \"function\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"renderType\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"((type: string) => Promise<ReactNode>) | undefined\",\n      \"simplifiedType\": \"function\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"options\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"GenerateTypeTableOptions | undefined\",\n      \"simplifiedType\": \"object\",\n      \"required\": false,\n      \"deprecated\": false\n    }\n  ]\n}}\n/>\n";
